  if (!itemId) {
    res.status(400).json({ error: 'itemId is required' });
    return;
  }
  const key = legacyFavoritesKey(projectId, favoriteType);
  const updated = (legacyFavoritesStore.get(key) || []).filter((id) => id !== itemId);
  legacyFavoritesStore.set(key, updated);
