/**
 * PUT /api/universal-crm/customers/:id
 * Update a customer
 */
app.put('/api/universal-crm/customers/:id', async (req, res) => {
  try {
    const { id } = req.params;
    const updates = req.body;

    // Build SET clause dynamically from provided fields
    const fieldMap: Record<string, string> = {
      name: 'name', email: 'email', phone: 'phone', company: 'company',
      profession: 'profession', projectType: 'project_type',
      budget: 'budget', status: 'status', tags: 'tags',
      notes: 'notes', source: 'source', customFields: 'custom_fields',
    };

    const setClauses: string[] = ['updated_at = now()'];
    const params: any[] = [];
    let idx = 1;

    for (const [jsKey, dbCol] of Object.entries(fieldMap)) {
      if (updates[jsKey] !== undefined) {
        setClauses.push(`${dbCol} = $${idx++}`);
        params.push(dbCol === 'custom_fields' ? JSON.stringify(updates[jsKey]) : updates[jsKey]);
      }
    }

    params.push(id);
    const result = await pool.query(
      `UPDATE crm_customers SET ${setClauses.join(', ')} WHERE id = $${idx} RETURNING *`,
      params
    );

    if (result.rows.length === 0) {
      return res.status(404).json({ error: 'Customer not found' });
    }

    const r = result.rows[0];
    return res.json({
      id: r.id,
      name: r.name || '',
      email: r.email || '',
      phone: r.phone || '',
      company: r.company || '',
      profession: r.profession || '',
      projectType: r.project_type || '',
      budget: r.budget ? parseFloat(r.budget) : undefined,
      status: r.status || 'lead',
      tags: r.tags || [],
      notes: r.notes || '',
      source: r.source || '',
      createdAt: r.created_at,
      updatedAt: r.updated_at,
      customFields: r.custom_fields || {},
      projectId: r.project_id || null,
    });
  } catch (error) {
    console.error('CRM customer update error:', error);
    return res.status(500).json({ error: 'Failed to update customer' });
  }
});

