app.put('/api/universal-crm/deals/:id', async (req, res) => {
  try {
    const allowed = ['customer_id', 'title', 'value', 'currency', 'stage', 'probability', 'expected_close_date', 'assigned_to', 'service_type', 'notes'];
    const setClauses = ['updated_at = now()'];
    const params: any[] = [];
    let idx = 1;
    for (const key of allowed) {
      if (req.body[key] !== undefined) {
        setClauses.push(`${key} = $${idx++}`);
        params.push(req.body[key]);
      }
    }
    params.push(req.params.id);
    const result = await pool.query(`UPDATE crm_deals SET ${setClauses.join(', ')} WHERE id = $${idx} RETURNING *`, params);
    if (result.rows.length === 0) return res.status(404).json({ error: 'Deal not found' });
    return res.json({ deal: result.rows[0] });
  } catch (error) {
    console.error('CRM deal update error:', error);
    return res.status(500).json({ error: 'Failed to update deal' });
  }
});

