    const { customerId, customer_id: cid, dealId, deal_id: did, type, subject, description, scheduledAt, scheduled_at: sa, direction, outcome } = req.body;
    const customer_id = customerId || cid || null;
    const deal_id = dealId || did || null;
    const scheduled_at = scheduledAt || sa || null;
