app.get('/api/universal-crm/tasks', async (req, res) => {
  try {
    const { customer_id, status, assigned_to, limit = '50' } = req.query as Record<string, string>;
    let where = 'WHERE 1=1';
    const params: any[] = [];
    let idx = 1;
    if (customer_id) { where += ` AND customer_id = $${idx++}`; params.push(customer_id); }
    if (status) { where += ` AND status = $${idx++}`; params.push(status); }
    if (assigned_to) { where += ` AND assigned_to = $${idx++}`; params.push(assigned_to); }

    const rows = await pool.query(
      `SELECT * FROM crm_tasks ${where} ORDER BY due_date ASC NULLS LAST, created_at DESC LIMIT $${idx}`,
      [...params, parseInt(limit) || 50]
    );
    return res.json({ tasks: rows.rows });
  } catch (error) {
    console.error('CRM tasks error:', error);
    return res.status(500).json({ error: 'Failed to fetch tasks' });
  }
});

