app.put('/api/universal-crm/tasks/:id', async (req, res) => {
  try {
    const allowed = ['customer_id', 'deal_id', 'title', 'description', 'assigned_to', 'priority', 'status', 'due_date', 'completed_at'];
    const setClauses = ['updated_at = now()'];
    const params: any[] = [];
    let idx = 1;
    for (const key of allowed) {
      if (req.body[key] !== undefined) {
        setClauses.push(`${key} = $${idx++}`);
        params.push(req.body[key]);
      }
    }
    params.push(req.params.id);
    const result = await pool.query(`UPDATE crm_tasks SET ${setClauses.join(', ')} WHERE id = $${idx} RETURNING *`, params);
    if (result.rows.length === 0) return res.status(404).json({ error: 'Task not found' });
    return res.json({ task: result.rows[0] });
  } catch (error) {
    console.error('CRM task update error:', error);
    return res.status(500).json({ error: 'Failed to update task' });
  }
});

